"use strict";(self.webpackChunkPromoScreen=self.webpackChunkPromoScreen||[]).push([[203],{60203:e=>{e.exports=JSON.parse('{"reviews":{"get_pregnant":[{"id":"gp_1","text":"Дуже сподобалося ваша програма точно вирахувала день овуляції завдяки чому я в той самий день завагітніла і потім цікаво і дізнаючись багато чому новому відслідковувала свою вагітність","userName":"Настя Бокоч"},{"id":"gp_2","text":"Найкраща програма!!!💚 З усіх якими користувалася. Аналізуючи дані які відмічаєш, автоматично відображаються поради по здоров\'ю...Тут не шкода навіть преміум версію купити ...","userName":"Alesia Müller"},{"id":"gp_3","text":"Додаток практичний та зручний. За декілька днів попереджає коли почнуться критичні дні, а коли овуляція. З ним дуже легко відстежити свій стан та ще додаток надає гарні поради. Мені він дуже сподобався у використанні тому я всім раджу його.","userName":"Александра Воловик"}],"track_cycle":[{"id":"tc_1","text":"Найкраща програма!!!💚 З усіх якими користувалася. Аналізуючи дані які відмічаєш, автоматично відображаються поради по здоров\'ю...Тут не шкода навіть преміум версію купити ..","userName":"Alesia Müller"},{"id":"tc_2","text":"дуже класна і зручна програма для жінок, в якій присутні додаткові функції і цікаві статті, які допомагають вивчати і розуміти процеси в жіночому організмі. розробникам велике ДЯКУЮ! 😊","userName":"Мар ’‎яна Шлапак"},{"id":"tc_3","text":"Дуже хороша програма. Завжди все точно показує. Можна слідкувати за станом свого здоров\'я, кількістю випитої води, вагою, довжиною та якістю сну, калоріями, з\'їденими за день і тощо.","userName":"Ольга Коваленко"}],"follow_pregnancy":[{"id":"fp_1","text":"Програма хороша з нею в мене пройшла і вагітність , дуже чекала нової неділі , було дуже цікаво читати нові статті як для мами так і для малечі , статті для малечі як в утробі так і від народження , для мами про її цикл, овуляция , поради...дякую flo що ти зімною😊","userName":"Алька Забитчук"},{"id":"fp_2","text":"Зручна та корисна програма! Користувалася нею також в період вагітності, де отримувала інфу по розвитку дитини і тим змінам, що відбуваються з жінкою та актуальні поради на кожен місяць вагітності.","userName":"Анна Алексеева"},{"id":"fp_3","text":"Дуже хороший додаток з найкориснішими порадами для здоров\'я. Тут можна відслідкувати не тільки менцикл, а щей вагітність.","userName":"Polina Godunko"}]}}')}}]);
